function countSequences(steps: number[], low: number, high: number): number {
  let count = 0;
  for (let s = low; s <= high; s++) {
    let v = s, ok = true;
    for (const d of steps) {
      v += d;
      if (v < low || v > high) { ok = false; break; }
    }
    if (ok) count++;
  }
  return count;
}

