function countSequences(steps: number[], low: number, high: number): number {
  let sum = 0, mn = 0, mx = 0;
  for (const d of steps) {
    sum += d;
    if (sum < mn) mn = sum;
    if (sum > mx) mx = sum;
  }
  return Math.max(0, high - low - (mx - mn) + 1);
}

